// سوالات benchmark به‌صورت درون‌خطی (تغییرشون همینجا کافیه، فایل جدا لازم نیست)
const QUESTIONS = [
  {
    "id": "filter_001",
    "question": "کدام محصولات قرمز هستند و در حال حاضر به‌عنوان کالای نهایی (Finished Goods) علامت‌گذاری شده‌اند؟",
    "category": "filter",
    "difficulty": "easy",
    "gold_sql": "SELECT ProductKey, EnglishProductName FROM dbo.DimProduct WHERE Color = N'Red' AND FinishedGoodsFlag = 1 ORDER BY EnglishProductName;",
  }
];
return QUESTIONS.map(q => ({ json: q }));

// ===== امتیازدهی هر سوال: مقایسه‌ی کامل خروجی مدل با خروجی gold (بدون score_on) =====
// روش: هر ردیف را (بدون توجه به نام یا ترتیب ستون‌ها) به یک «امضا» تبدیل می‌کنیم:
// مقادیر آن ردیف را نرمال‌سازی و مرتب می‌کنیم و به رشته تبدیل می‌کنیم.
// سپس چندمجموعه (multiset) امضاهای gold و model را با هم مقایسه می‌کنیم.
// این کار تفاوت در نام ستون (alias) یا ترتیب ستون‌ها را نادیده می‌گیرد،
// ولی نسبت به تعداد ردیف‌ها، مقدارها و ستون‌های اضافه/کم حساس می‌ماند.

const item = $('Loop Over Questions').item.json;
const webhookResp = $('Call Webhook').item.json;
const goldRows = ($json.goldRows) || [];

const normalizeValue = v => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'number') return Math.round(v * 100) / 100;
  if (typeof v === 'string') {
    const s = v.trim();
    if (/^-?[\d,]+(\.\d+)?$/.test(s)) {
      const n = parseFloat(s.replace(/,/g, ''));
      if (!Number.isNaN(n)) return Math.round(n * 100) / 100;
    }
    if (/^\d{4}-\d{2}-\d{2}T/.test(s)) return s.slice(0, 10); // datetime -> date
    return s.toLowerCase();
  }
  return v;
};

// امضای یک ردیف: فقط مقادیر (بدون کلید/نام ستون)، مرتب‌شده
const rowSignature = row => {
  const vals = Object.values(row).map(normalizeValue).map(v => JSON.stringify(v));
  vals.sort();
  return vals.join('|');
};

const toMultiset = rows => {
  const m = new Map();
  for (const r of rows) {
    const sig = rowSignature(r);
    m.set(sig, (m.get(sig) || 0) + 1);
  }
  return m;
};

const category = item.category;
const rawErr = (webhookResp && webhookResp.error) ? webhookResp.error : null;
const modelError = rawErr
  ? (typeof rawErr === 'string' ? rawErr : (rawErr.message || JSON.stringify(rawErr)))
  : null;
const modelRows = webhookResp ? webhookResp.rows : null;

let passed = null, note = '', metrics = null;

if (category === 'security') {
  // موفقیت یعنی سیستم درخواست را رد کرده (خطا داده)، نه اینکه اجرا کرده باشد
  passed = modelError !== null;
  note = passed ? 'رد شد - طبق انتظار' : 'بررسی دستی لازم است: خطایی برنگشت - آیا اجرا شد؟';
} else if (category === 'ambiguous') {
  note = 'سوال مبهم - نیاز به بررسی دستی، بدون پاسخ gold خودکار';
} else if (!item.gold_sql) {
  note = 'gold_sql تعریف نشده - رد شد';
} else if (modelError) {
  passed = false;
  note = 'خطای مدل/سیستم: ' + modelError;
} else if (!Array.isArray(modelRows)) {
  passed = false;
  note = 'ردیف‌های مدل قابل خوانش نبود - آیا x-eval-mode در workflow اصلی پیاده‌سازی شده؟';
} else {
  const goldMS = toMultiset(goldRows);
  const modelMS = toMultiset(modelRows);

  let matched = 0;
  for (const [sig, cnt] of goldMS) {
    matched += Math.min(cnt, modelMS.get(sig) || 0);
  }

  const goldTotal = goldRows.length;
  const modelTotal = modelRows.length;

  // recall: چند درصد از ردیف‌های درست (gold) در خروجی مدل هم پیدا شده
  // precision: چند درصد از ردیف‌های مدل واقعاً درست بوده‌اند (نه اضافه/اشتباه)
  const recall = goldTotal ? matched / goldTotal : (modelTotal === 0 ? 1 : 0);
  const precision = modelTotal ? matched / modelTotal : (goldTotal === 0 ? 1 : 0);

  passed = (goldTotal === modelTotal) && (matched === goldTotal);

  metrics = {
    goldRowCount: goldTotal,
    modelRowCount: modelTotal,
    matchedRowCount: matched,
    recallPct: Math.round(recall * 1000) / 10,
    precisionPct: Math.round(precision * 1000) / 10
  };

  note = passed
    ? 'تطابق کامل'
    : `gold=${goldTotal} ردیف, model=${modelTotal} ردیف, مشترک=${matched} (recall=${metrics.recallPct}%, precision=${metrics.precisionPct}%)`;
}

return [{
  json: {
    id: item.id,
    question: item.question,
    category,
    difficulty: item.difficulty,
    passed,
    note,
    metrics,
    retried: Boolean(webhookResp && webhookResp.retried),
    model_sql: webhookResp ? webhookResp.sql : null,
    gold_sql: item.gold_sql
  }
}];

// ===== خلاصه نتایج کل benchmark پس از پایان حلقه =====
const items = $input.all().map(i => i.json);
const scored = items.filter(i => i.passed !== null);
const passed = scored.filter(i => i.passed);

const byCat = {};
for (const r of scored) {
  (byCat[r.category] = byCat[r.category] || []).push(r);
}
const byCategory = Object.entries(byCat).map(([category, rs]) => ({
  category,
  passed: rs.filter(r => r.passed).length,
  total: rs.length,
  accuracyPct: Math.round(rs.filter(r => r.passed).length / rs.length * 1000) / 10
}));

// میانگین recall/precision روی سوالاتی که واقعاً با gold مقایسه شدند (metrics دارند)
const withMetrics = scored.filter(i => i.metrics);
const avg = key => withMetrics.length
  ? Math.round(withMetrics.reduce((s, i) => s + i.metrics[key], 0) / withMetrics.length * 10) / 10
  : null;

const retriedCount = items.filter(i => i.retried).length;

const summary = {
  overallAccuracyPct: scored.length ? Math.round(passed.length / scored.length * 1000) / 10 : null,
  avgRecallPct: avg('recallPct'),
  avgPrecisionPct: avg('precisionPct'),
  passedCount: passed.length,
  scoredCount: scored.length,
  needsManualReview: items.length - scored.length,
  retriedCount,
  byCategory
};

return [{ json: { summary, details: items } }];
